spec.definitions:
def ratIdent (k : Nat) : Prop :=
  (1 : ℚ) / (k * (k + 1)) = (1 : ℚ) / k - (1 : ℚ) / (k + 1)

def ratStrict (k : Nat) : Prop :=
  (1 : ℚ) / (k * (k + 1)) < (1 : ℚ) / k

def checkOne (k : Nat) : Bool :=
  decide (ratIdent (k + 1)) && decide (ratStrict (k + 1))

def checkRange (n : Nat) : Bool :=
  (List.range n).all checkOne
